def get_sts9_blocks():
    # Standard STS(9) construction (affine plane of order 3)
    # Points 0-8
    blocks = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [1, 5, 6], [2, 3, 7],
        [0, 5, 7], [1, 3, 8], [2, 4, 6]
    ]
    return blocks

def construct_bibd():
    sts_blocks = get_sts9_blocks()
    # Repeat each block 3 times
    all_blocks = []
    for b in sts_blocks:
        for _ in range(3):
            all_blocks.append(b)

    # Create 9x36 matrix
    matrix = [[0 for _ in range(36)] for _ in range(9)]
    for col_idx, block in enumerate(all_blocks):
        for point in block:
            matrix[point][col_idx] = 1

    return matrix

