import random

def solve_costas_heuristic(n):
    for _ in range(10000):
        p = []
        used_rows = [False] * n
        used_diffs = set()

        def backtrack(col):
            if col == n:
                return True

            # Try rows in a random order
            rows = list(range(n))
            random.shuffle(rows)

            for row in rows:
                if not used_rows[row]:
                    # Check if this row is valid
                    valid = True
                    new_diffs = []
                    for prev_col in range(col):
                        dr = col - prev_col
                        dc = row - p[prev_col]
                        if (dr, dc) in used_diffs:
                            valid = False
                            break
                        new_diffs.append((dr, dc))

                    if valid:
                        p.append(row)
                        used_rows[row] = True
                        for diff in new_diffs:
                            used_diffs.add(diff)

                        if backtrack(col + 1):
                            return True

                        # Backtrack
                        for diff in new_diffs:
                            used_diffs.remove(diff)
                        used_rows[row] = False
                        p.pop()
            return False

        if backtrack(0):
            return p
    return None

