def is_graceful(labels):
    # labels is a list of 15 integers
    # G_{5,3} has 15 vertices, 40 edges
    # Edges:
    # Within cliques: (g,i), (g,j) for g in 0..2, 0 <= i < j <= 4
    # Between cliques: (g,i), (g+1,i) for g in 0..1, i in 0..4

    edges = []
    for g in range(3):
        for i in range(5):
            for j in range(i + 1, 5):
                edges.append((labels[g*5 + i], labels[g*5 + j]))
    for g in range(2):
        for i in range(5):
            edges.append((labels[g*5 + i], labels[(g+1)*5 + i]))

    edge_labels = [abs(u - v) for (u, v) in edges]

    if len(set(edge_labels)) != 40:
        return False
    if min(edge_labels) < 1 or max(edge_labels) > 40:
        return False
