import random

def get_girth(adj, n):
    for i in range(n):
        dist = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[v] >= dist[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 7:
                        return cycle_len
    return 100

def generate_random_3_regular(n):
    while True:
        edges = []
        nodes = []
        for i in range(n):
            nodes.extend([i, i, i])
        random.shuffle(nodes)

        adj = [set() for _ in range(n)]
        possible = True
        for i in range(0, len(nodes), 2):
            u, v = nodes[i], nodes[i+1]
            if u == v or v in adj[u]:
                possible = False
                break
            adj[u].add(v)
            adj[v].add(u)
            edges.append(tuple(sorted((u, v))))

        if possible:
            return adj, edges

def solve():
    for _ in range(50000):
        adj, edges = generate_random_3_regular(24)
        if get_girth(adj, 24) >= 7:
            return edges
    return None

