        # 1. Group g has < group_size players
        # 2. No player in group g has played with p before

        # Let's count how many players in each group have already played with p
        # We want to pick a group that minimizes this count (ideally 0)

        group_conflicts = [0 for _ in range(n_groups)]
        group_sizes = [0 for _ in range(n_groups)]
        for i in range(n_golfers):
